const body = items[0].json;
if(!body.fileId){ throw new Error('fileId missing'); }
return [{ json: { fileId: body.fileId, localPath: `/tmp/${body.fileId}` } }];

const out = [];
const payload = items[0].json;
const facts = (payload.facts || []);
for (const f of facts) {
  out.push({ json: {
    investee_id: null,
    holding_id: null,
    metric_code: f.metric_code,
    period_start: f.period_start,
    period_end: f.period_end,
    value: Number(f.value),
    source: f.source || 'LLM Extract',
    verification_level: f.verification_level || 'Issuer Reported',
    data_quality_score: Number(f.data_quality_score || 0.6)
  }});
}
return out;
